pragma cashscript ~0.13.0;

/**
 * AuthHeadVault: Modified authorization vault with strict authhead requirements
 * 
 * A authorization vault with additional output constraints to maintain authhead identity:
 * - Must be the first input (index 0)
 * - First output must not contain any tokens
 * - Must be authorized with permission bit 0x0002
 *
 * Authhead identity burning to support full lifecycle of BCMR identities
 * - No input positioning restriction, burn X identities in a single transaction
 * - First output must be a no value, no token OP_RETURN
 * - No restrictions on data embedded in OP_RETURN
 * - Must be authorized with permission bit 0x0020
 * 
 * Used specifically for authorizing fund's BCMR update operations.
 * 
 * Parameters:
 *   authToken: Token category that authorizes fund creation
 */
contract AuthHeadVault(bytes32 authToken)
{
    /**
     * update(): Authorizes authhead update with strict transaction structure
     * 
     * Supports:
     * - No BCMR update restrictions
     *
     * Ensures:
     * - This vault is the first input (positioning control)
     * - First output has no tokens (clean state to maintain authhead integrity)
     * - Authorization token is present with bit 0x0002 (authhead update permission)
     */
    function update() {
        // This vault MUST be the first input, ensures only one update but prevents combining identities
        require(this.activeInputIndex == 0, "expected to be the first input");
        require(tx.inputs[this.activeInputIndex].lockingBytecode == tx.outputs[this.activeInputIndex].lockingBytecode);
        // First output must have no tokens (ensures clean state to maintain authhead integrity)
        require(tx.outputs[this.activeInputIndex].tokenCategory == 0x, "no token allowed on authhead");

        // Check for authorization token in ANY input
        // Bit 0x0002 in commitment indicates authhead (BCMR maintenance) authorization
        bool authorized = false;
        int inputIndex = 0;
        do {
            if(tx.inputs[inputIndex].tokenCategory == authToken) {
                if((bytes(tx.inputs[inputIndex].nftCommitment.slice(1, 3)) & bytes(0x0002)) == 0x0002) {
                    authorized = true;
                }
            }
            inputIndex = inputIndex + 1;
        } while(inputIndex < tx.inputs.length && !authorized);
        require(authorized, "unauthorized user");
    }

    /**
     * burn(): Authorizes authhead identity burning with strict transaction structure
     *
     * Supports:
     * - Multiple identity burning in a single tx
     *
     * Ensures:
     * - The outputs' authhead is an OP_RETURN
     * - The outputs' authhead has no value or tokens
     * - Authorization token is present with bit 0x0020 (authhead identity burning permission)
     */
    function burn() {
        // First output must be an OP_RETURN
        require(tx.outputs[0].lockingBytecode.slice(0, 1) == 0x6a, "first output must be an OP_RETURN");
        // First output must have no tokens or value (ensures clean state to maintain authhead integrity)
        require(tx.outputs[0].tokenCategory == 0x, "no token allowed on authhead");
        require(tx.outputs[0].value == 0);

        // Check for authorization token in ANY input
        // Bit 0x0020 in commitment indicates authhead (BCMR maintenance) identity burning
        bool authorized = false;
        int inputIndex = 0;
        do {
            if(tx.inputs[inputIndex].tokenCategory == authToken) {
                if((bytes(tx.inputs[inputIndex].nftCommitment.slice(1, 3)) & bytes(0x0020)) == 0x0020) {
                    authorized = true;
                }
            }
            inputIndex = inputIndex + 1;
        } while(inputIndex < tx.inputs.length && !authorized);
        require(authorized, "unauthorized user");
    }
}
